"""
	Local helper function that takes a pettingzoo config path and returns it in
	the service_class/service_name format expected in this module
	"""
def _config_path_to_class_and_name(path: Any) -> object {
    path = path.split(".")[0];
    parts = path.split("/");
    if (len(parts) >= 2) {
        service_class = parts[-2];
        service_name = parts[-1];
        return (service_class, service_name);
    } else {
        raise Exception(("Config path cannot be parsed: %s" % path));
    }
}

"""
    appends the given argument to a command line such that CommandLineToArgvW will return
    the argument string unchanged.
    """
def win_concat_quote(command_line: str, argument: str) -> str {
    result = (command_line + " ") if command_line else "";
    if argument {
        if (len(argument.split()) == 1) {
            if ('"' not in argument) {
                result += argument;
                return result;
            }
        }
    }
    result += '"';
    it = 0;
    end = len(argument);
    while (it < end) {
        number_backslashes = 0;
        char = argument[it];
        while (char == '\\') {
            it += 1;
            number_backslashes += 1;
            try {
                char = argument[it];
            } except IndexError {
                break;
            }
        }
        if (it >= end) {
            result += '\\' * (number_backslashes * 2);
            break;
        } elif (char == '"') {
            result += '\\' * ((number_backslashes * 2) + 1);
            result += char;
        } else {
            result += '\\' * number_backslashes;
            result += char;
        }
        it += 1;
    }
    result += '"';
    return result;
}

